package main

import (
	"encoding/json"
	"fmt"
	"net/http"
)

type SearchRequest struct {
	Query string `json:"query"`
	Limit int    `json:"limit"`
}

type SearchResponse struct {
	Query   string   `json:"query"`
	Results []string `json:"results"`
	Total   int      `json:"total"`
}

// searchHandler handles GET /search?q=golang&limit=5
func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// TODO: read 'q' query param
	q := r.URL.Query().Get("q")
	if q == "" {
		http.Error(w, "query param 'q' is required", http.StatusBadRequest)
		return
	}

	// TODO: read 'limit' query param (default to 10)
	// Hint: use strconv.Atoi

	results := []string{"result1 for " + q, "result2 for " + q}
	response := SearchResponse{
		Query:   q,
		Results: results,
		Total:   len(results),
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(response)
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/search", searchHandler)

	fmt.Println("Server on :8080 — try: curl 'localhost:8080/search?q=golang'")
	http.ListenAndServe(":8080", mux)
}
